INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(19103, 'koKR', 'Wiedziałem, że książę się rozgniewa, ale ja... nie byłem sobą. Musiałem ich wypuścić! Widzicie, przemawia do mnie ten wielki. Chwila – obcy. Nie przysłał was Kael\'thas! Dobrze... Po prostu powiem księciu, że to wy uwolniliście więźniów!', '', 0),
(19104, 'koKR', 'Naaru trzymali w tych celach jedne z najniebezpieczniejszych istot, jakie istnieją. Pozwólcie, że przedstawię wam kolejną...', '', 0),
(19106, 'koKR', 'Tak, tak... kolejną! Twoja wola należy do mnie!', '', 0),
(19107, 'koKR', 'Oto następna przerażająca istota o niepojętej mocy!', '', 0),
(19109, 'koKR', 'Co to? Marny gnom? Postaram się lepiej, o wielki.', '', 0),
(19110, 'koKR', 'Anarchia! Chaos! Och, jakiś ty mądry! Tak, teraz to widzę, oczywiście!', '', 0),
(19111, 'koKR', 'Została ostatnia cela. Tak, o wielki, natychmiast!', '', 0),
(19114, 'koKR', 'Witaj, o wielki. Jestem twoim pokornym sługą.', '', 0),
(19392, 'koKR', 'Energia Pustki gromadzi się u podstawy – %s!', 'Energia Pustki gromadzi się u podstawy – %s!', 0),
(19967, 'koKR', 'Nareszcie jest na kim wyładować frustrację!', '', 0),
(19968, 'koKR', 'Przyszliście zabić Dalliah? Mogę popatrzeć?', '', 0),
(19969, 'koKR', 'Tak, to było całkiem satysfakcjonujące.', '', 0),
(19971, 'koKR', 'Do broni!', '', 0),
(19972, 'koKR', 'Brońcie się, choć na niewiele się to zda...', '', 0),
(19973, 'koKR', 'Wiedziałem, że to... jedyne wyjście.', '', 0),
(19974, 'koKR', 'Kłopoty, Dalliah? Jak miło.', '', 0),
(19975, 'koKR', 'To może być twój koniec, Dalliah. Co za szkoda.', '', 0),
(19976, 'koKR', 'Proponuję nową strategię: ty ściągasz na siebie ich ataki, a ja zbieram posiłki.', '', 0),
(19977, 'koKR', 'Wreszcie! Dobra robota!', '', 0),
(19978, 'koKR', '', 'Nierozsądnie jest mnie gniewać!', 0),
(19979, 'koKR', '', 'Nie przejmujcie się mną, zabijcie lepiej tego bezużytecznego tępaka!', 0),
(19980, 'koKR', '', 'Zupełnie nieskuteczne. Jak pewien ktoś, kogo znam.', 0),
(19981, 'koKR', '', 'Wybraliście złego przeciwnika.', 0),
(19982, 'koKR', '', 'Zbierzcie burzę!', 0),
(19983, 'koKR', '', 'Posiekam was na kawałki!', 0),
(19984, 'koKR', '', 'Tak jest znacznie lepiej.', 0),
(19985, 'koKR', '', 'Ach... właśnie tego mi było trzeba.', 0),
(19986, 'koKR', '', 'Teraz naprawdę się wściekłam.', 0),
(19987, 'koKR', '', 'Za dużo jak na ciebie, wróżbito?', 0),
(19988, 'koKR', '', 'Pewnie skończy się na tym, że sama ich wszystkich pokonam.', 0),
(19989, 'koKR', '', 'Przywykłam już do sprzątania po tobie.', 0),
(19990, 'koKR', '', 'Gratulacje. Od lat chciałam to zrobić.', 0),
(20045, 'koKR', 'Energia życiowa do... pochłonięcia.', '', 0),
(20046, 'koKR', 'To naczynie jest puste.', '', 0),
(20047, 'koKR', 'Koniec... z... życiem.', '', 0),
(20048, 'koKR', 'Cień... was pochłonie.', '', 0),
(20049, 'koKR', 'Ciemność... pochłania wszystko.', '', 0),
(20050, 'koKR', 'Pustka... wzywa.', '', 0),
(20051, 'koKR', 'Wołałaś mnie?', '', 0),
(20052, 'koKR', 'Pewnie do najcięższej roboty.', '', 0),
(20053, 'koKR', 'W takim razie z całym zaangażowaniem będę cię ignorował.', '', 0),
(20054, 'koKR', 'To ty powinnaś być... Zaraz, mamy gości...', '', 0),
(20055, 'koKR', '', 'Po co miałabym cię wołać?', 0),
(20056, 'koKR', '', 'Kiedy będę potrzebować kogoś, kto paraduje jak przekarmiony paw, zawołam cię.', 0),
(20057, 'koKR', '', 'Co ty możesz wiedzieć o zaangażowaniu, sheet-sah?', 0);
